import React, { useState, useEffect } from "react";
import {
    TextField,
    Box,
    Button,
    Typography,
    List,
    ListItem,
    ListItemText,
    Checkbox,
    FormGroup,
    FormControlLabel,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
} from "@mui/material";
import { ref, get, set, push, update } from "firebase/database";
import { db } from "./firebaseConfig";
import { useNavigate } from "react-router-dom";

const Alumnos = () => {
    const [alumnos, setAlumnos] = useState([]);
    const [addDialogOpen, setAddDialogOpen] = useState(false);
    const [pagoDialogOpen, setPagoDialogOpen] = useState(false);
    const [monto, setMonto] = useState("");
    const [fechaPago, setFechaPago] = useState("");
    const [alumnoSeleccionado, setAlumnoSeleccionado] = useState(null);
    const [totalGanancias, setTotalGanancias] = useState(0);
    const navigate = useNavigate();
    const [nuevoAlumno, setNuevoAlumno] = useState({ nombre: "", apellido: "", fechaIngreso: "" });


    const agregarAlumno = async () => {
        if (!nuevoAlumno.nombre || !nuevoAlumno.apellido || !nuevoAlumno.fechaIngreso) {
            alert("Por favor, completa todos los campos.");
            return;
        }

        try {
            const alumnosRef = ref(db, "alumnos");
            const nuevoAlumnoRef = push(alumnosRef);
            await set(nuevoAlumnoRef, { ...nuevoAlumno, clases: [false, false, false, false] });

            setNuevoAlumno({ nombre: "", apellido: "", fechaIngreso: "" });
            setAddDialogOpen(false);
            cargarAlumnos();
        } catch (error) {
            console.error("Error al agregar el alumno:", error);
        }
    };
    useEffect(() => {
        cargarAlumnos();
    }, []);

    useEffect(() => {
        calcularTotalGanancias();
    }, [alumnos]);

    const cargarAlumnos = async () => {
        try {
            const alumnosRef = ref(db, "alumnos");
            const pagosRef = ref(db, "pagos");
            const snapshotAlumnos = await get(alumnosRef);
            const snapshotPagos = await get(pagosRef);

            let pagosData = {};
            if (snapshotPagos.exists()) {
                pagosData = snapshotPagos.val();
            }

            if (snapshotAlumnos.exists()) {
                const data = snapshotAlumnos.val();
                const mesActual = new Date().getMonth() + 1;
                const anioActual = new Date().getFullYear();

                const alumnosList = Object.keys(data).map((key) => {
                    const pagosFiltrados = pagosData[key]
                        ? Object.values(pagosData[key]).filter(pago => {
                            const fecha = new Date(pago.fechaPago + "T00:00:00");
                            return fecha.getMonth() + 1 === mesActual && fecha.getFullYear() === anioActual;
                        })
                        : [];

                    return {
                        ...data[key],
                        id: key,
                        pagos: pagosFiltrados, // Solo pagos del mes actual
                        clases: data[key].clases || [false, false, false, false],
                    };
                });

                setAlumnos(alumnosList);
            }
        } catch (error) {
            console.error("Error al cargar los alumnos:", error);
        }
    };

    const calcularTotalGanancias = () => {
        const mesActual = new Date().getMonth() + 1;
        const anioActual = new Date().getFullYear();
        let total = 0;

        alumnos.forEach(alumno => {
            alumno.pagos.forEach(pago => {
                const fecha = new Date(pago.fechaPago + "T00:00:00");
                if (fecha.getMonth() + 1 === mesActual && fecha.getFullYear() === anioActual) {
                    total += pago.monto;
                }
            });
        });

        setTotalGanancias(total);
    };

    const registrarPago = async () => {
        if (!alumnoSeleccionado || !monto || !fechaPago) {
            alert("Por favor, completa todos los campos.");
            return;
        }

        try {
            const pagosRef = ref(db, `pagos/${alumnoSeleccionado.id}`);
            const nuevoPagoRef = push(pagosRef);
            await set(nuevoPagoRef, {
                monto: parseFloat(monto),
                fechaPago,
                mes: new Date(fechaPago).getMonth() + 1,
                anio: new Date(fechaPago).getFullYear()
            });

            setMonto("");
            setFechaPago("");
            setPagoDialogOpen(false);
            cargarAlumnos();
        } catch (error) {
            console.error("Error al registrar el pago:", error);
        }
    };
    const toggleClase = async (alumnoId, index) => {
        try {
            const alumno = alumnos.find((a) => a.id === alumnoId);
            if (!alumno) return;

            const nuevasClases = [...alumno.clases];
            nuevasClases[index] = !nuevasClases[index];

            await update(ref(db, `alumnos/${alumnoId}`), { clases: nuevasClases });
            setAlumnos((prevAlumnos) =>
                prevAlumnos.map((a) => (a.id === alumnoId ? { ...a, clases: nuevasClases } : a))
            );
        } catch (error) {
            console.error("Error al actualizar las clases:", error);
        }
    };
    useEffect(() => {
        verificarCambioDeMes();
    }, [alumnos]);

    

    const verificarCambioDeMes = async () => {
        try {
            const configRef = ref(db, "config/ultimoMes");
            const snapshot = await get(configRef);
            const mesActual = new Date().getMonth() + 1;

            if (!snapshot.exists() || snapshot.val() !== mesActual) {
                await resetearClases();
                await set(configRef, mesActual); // Guardar el nuevo mes
            }
        } catch (error) {
            console.error("Error al verificar el cambio de mes:", error);
        }
    };

    const resetearClases = async () => {
        try {
            const alumnosRef = ref(db, "alumnos");
            const snapshot = await get(alumnosRef);

            if (snapshot.exists()) {
                const alumnosData = snapshot.val();
                const updates = {};

                Object.keys(alumnosData).forEach((key) => {
                    updates[`alumnos/${key}/clases`] = [false, false, false, false];
                });

                await update(ref(db), updates);
                console.log("Clases reiniciadas para el nuevo mes.");
            }
        } catch (error) {
            console.error("Error al resetear las clases:", error);
        }
    };


    return (
        <Box sx={{ padding: 2, display:'flex',justifyContent:'center', alignContent:'center', flexDirection:'column'}}>
            <Dialog open={addDialogOpen} onClose={() => setAddDialogOpen(false)} sx={{borderRadius:7}}>
                <DialogTitle>Agregar Nuevo Alumno</DialogTitle>
                <DialogContent>
                    <TextField label="Nombre" fullWidth value={nuevoAlumno.nombre} onChange={(e) => setNuevoAlumno({ ...nuevoAlumno, nombre: e.target.value })} margin="dense" />
                    <TextField label="Apellido" fullWidth value={nuevoAlumno.apellido} onChange={(e) => setNuevoAlumno({ ...nuevoAlumno, apellido: e.target.value })} margin="dense" />
                    <TextField label="Fecha de Ingreso" type="date" fullWidth InputLabelProps={{ shrink: true }} value={nuevoAlumno.fechaIngreso} onChange={(e) => setNuevoAlumno({ ...nuevoAlumno, fechaIngreso: e.target.value })} margin="dense" />
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setAddDialogOpen(false)}>Cancelar</Button>
                    <Button sx={{borderRadius:6}} onClick={agregarAlumno} color="secondary" variant="contained">Agregar</Button>
                </DialogActions>
            </Dialog>
        <Box sx={{display:'flex', flexDirection:'row', justifyContent:'center', alignContent:'center'}}> 
            <Button variant="contained" sx={{ borderRadius: 7, mb: 3, width:'50%' }} color="secondary" onClick={() => setAddDialogOpen(true)}>Agregar Alumno</Button>
            <Button variant="contained" color="error" sx={{ mb: 3, ml: 2, borderRadius: 7, width:'50%' }} onClick={() => navigate('/ventaVarios')}>
                Venta de Varios
            </Button>
            </Box> 
            <Typography variant="h5" gutterBottom textAlign="center" mt='5'>Alumnos Ingresados</Typography>
            <List >
                {alumnos.map((alumno) => (
                    <ListItem key={alumno.id} sx={{backgroundColor:'white', display: "flex", border:2, borderColor:'violet', borderRadius:4, margin:0.6, padding:1, display:'flex', flexDirection:'column'}}>
                        <ListItemText
                            sx={{  }}
                            primary={
                            <Box sx={{display:'flex', flexDirection:'row',  justifyContent:'space-around', alignContent:'center', alignItems:'center'}}>
                             <Box sx={{display:'flex', flexDirection:'column'}}> 
                                <Typography sx={{ fontWeight: "bold",mr:1.5 }}>
                                    {`${alumno.nombre}  ${alumno.apellido}`}
                                </Typography>
                                    </Box> 
                                    <Box><Typography variant="body2" color="violet">  Ingreso: {alumno.fechaIngreso}</Typography></Box>
                                    <Box sx={{ display: 'flex', flexDirection: 'row'}}>
                                        <Button color="warning" sx={{ borderRadius: 8, width:'auto' }} onClick={() => { setAlumnoSeleccionado(alumno); setPagoDialogOpen(true); }}>Nuevo Pago</Button>
                                    </Box> 
                                </Box>
                            }
                            secondary={
                                <>
                                  
                                    <Typography textAlign='center' fontSize='0.7rem' sx={{ mt: 1 }}>ASISTECIAS {new Date().toLocaleString('es-ES', { month: 'long' }).toUpperCase()}</Typography>
                                    <FormGroup row sx={{ display: "flex", justifyContent: "center" }}>
                                        {alumno.clases.map((checked, index) => (
                                            <FormControlLabel
                                                key={index}
                                                control={
                                                    <Checkbox
                                                        checked={checked}
                                                        onChange={() => toggleClase(alumno.id, index)}
                                                        sx={{
                                                            transform: "scale(0.8)", // Reduce el tamaño
                                                            color: "purple", // Cambia el color cuando está desmarcado
                                                            "&.Mui-checked": { color: "green" }, // Cambia el color cuando está marcado
                                                        }}
                                                    />
                                                }
                                                label={` ${index + 1}`}
                                            />
                                        ))}
                                    </FormGroup>
                                    <Box sx={{ display: 'flex', justifyContent: 'center', mr: 1, alignItems: 'center', alignContent: 'center' }}>
                                        {alumno.pagos.map((pago, index) => (
                                            <Box sx={{ display: 'flex', alignItems: 'center' }} key={index}>
                                                <Typography fontSize='0.8rem' sx={{ mr: 1 }}>{pago.fechaPago} </Typography>
                                             
                                            </Box>
                                        ))}
                                        <Typography color="brown" fontWeight="" fontSize='1.1rem'>
                                            ${alumno.pagos
                                                .filter(pago => {
                                                    const fecha = new Date(pago.fechaPago + "T00:00:00");
                                                    return fecha.getMonth() + 1 === new Date().getMonth() + 1 &&
                                                        fecha.getFullYear() === new Date().getFullYear();
                                                })
                                                .reduce((total, pago) => total + pago.monto, 0)}
                                        </Typography>

                                        {alumno.pagos.length > 0 && (
                                            <Typography color='white' fontSize='0.5rem' fontWeight='bold' sx={{ backgroundColor: 'green', ml: 1, padding: 0.3, borderRadius: 1 }}>
                                                PAGADO
                                            </Typography>
                                        )}
                                        <Typography sx={{ color: 'black', ml:0.5 }} fontSize='0.6rem'>
                                            {new Date().toLocaleString('es-ES', { month: 'long' }).toUpperCase()}
                                        </Typography>
                                    </Box>


                                </>
                            }
                        />


                    </ListItem>
                ))}
            </List>
          <Box sx={{backgroundColor:'white', mt:4, padding:2, boxShadow:'4', borderRadius:7, display:'flex', justifyContent:'center', alignContent:'center', alignItems:'center'}}>
            <Typography variant="h6" color="green" sx={{mr:2}}>
                    Total de Ganancias del Mes: <Typography  variant='h4' color="red" fontWeight={'bold'}> ${totalGanancias}</Typography>
            </Typography>
         
            </Box>
            {/* Dialogo para registrar pagos */}
            <Dialog open={pagoDialogOpen} onClose={() => setPagoDialogOpen(false)}>
                <DialogTitle>Registrar Pago</DialogTitle>
                <DialogContent>
                    <TextField label="Monto" type="number" fullWidth value={monto} onChange={(e) => setMonto(e.target.value)} margin="dense" />
                    <TextField label="Fecha de Pago" type="date" fullWidth InputLabelProps={{ shrink: true }} value={fechaPago} onChange={(e) => setFechaPago(e.target.value)} margin="dense" />
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setPagoDialogOpen(false)}>Cancelar</Button>
                    <Button onClick={registrarPago} color="primary" variant="contained">Confirmar Pago</Button>
                </DialogActions>
            </Dialog>
         <Box sx={{display:'flex',justifyContent:'end',mt:3}}>
               <Typography fontSize='0.7rem'>Powered By PaBLo A.</Typography>
              </Box>
        </Box>
    );
};

export default Alumnos;
